-- Genshin income catalog (bookkeeping): every primogem / fate source per version, 1.0 → 7.2 (estimate).
-- Source: the community "Genshin Bookkeeping" sheet maintained by sectoidfodder (numbers per 42-day version; repeating rows are per-version averages).
-- kind / minutes / requires are this site's own classification and rough time estimates — admins can edit them on /income.
-- Run after 0009 (safe to re-run: replaces the catalog rows for genshin; per-account done/skip marks survive by (version, seq)).
create temp table _inc(version text, seq int, section text, kind text, name text, primos numeric, intertwined numeric, acquaint numeric, resin numeric, mora numeric, extra jsonb, minutes int, requires text[], is_estimate boolean);
select 'genshin', version, seq, section, kind, name, primos, intertwined, acquaint, resin, mora, extra, minutes, requires, is_estimate from _inc
on conflict (game_id, version, seq) do update set section = excluded.section, kind = excluded.kind, name = excluded.name, primos = excluded.primos,
  intertwined = excluded.intertwined, acquaint = excluded.acquaint, resin = excluded.resin, mora = excluded.mora, extra = excluded.extra,
  minutes = excluded.minutes, requires = excluded.requires, is_estimate = excluded.is_estimate;
delete from public.income_items i where i.game_id = 'genshin' and not exists (select 1 from _inc t where t.version = i.version and t.seq = i.seq);
select kind, count(*), sum(primos)::int as primos from public.income_items where game_id = 'genshin' group by kind order by kind;
drop table _inc;
